    config::ValidatorConfig,
    indexer::EventIndexer,
    tasks::{dispatcher::TaskDispatcher, TaskStore, ClaimStore},
    startup::ensure_weth_approval,
};
use std::str::FromStr;
use common::{restore_pristine, advance_time, advance_past_epoch, send_messages};
use alloy::providers::Provider;

/// The outbox's `hashClaim`, recomputed locally.
///
/// The bot never calls `hashClaim` - it only ever compares the stored `claimHashes[epoch]`
/// against a preimage it built itself - so there is no ABI binding for it. The packing is
/// the outbox's own (`VeaOutboxArbToEth.sol:506`): 32-byte state root, 20-byte claimer,
/// three `uint32`s, the one-byte `Party` enum, 20-byte challenger - 85 bytes, keccak256'd.
fn hash_claim(claim: &vea_validator::contracts::Claim) -> FixedBytes<32> {
    let mut packed = Vec::with_capacity(85);
    packed.extend_from_slice(claim.stateRoot.as_slice());
    packed.extend_from_slice(claim.claimer.as_slice());
    packed.extend_from_slice(&claim.timestampClaimed.to_be_bytes());
    packed.extend_from_slice(&claim.timestampVerification.to_be_bytes());
    packed.extend_from_slice(&claim.blocknumberVerification.to_be_bytes());
    // Spelled out rather than cast, so the test asserts the enum's on-chain encoding
    // (`enum Party { None, Claimer, Challenger }`) instead of inheriting it.
    packed.push(match claim.honest {
        vea_validator::contracts::Party::None => 0u8,
